"""Half-open integer interval utilities."""


def _clean(intervals):
    """Filter empty/inverted intervals and normalize to tuples of ints."""
    cleaned = []
    for start, end in intervals:
        if start < end:
            cleaned.append((int(start), int(end)))
    return cleaned


def merge(intervals):
    """Merge overlapping and touching intervals; return sorted list of tuples."""
    cleaned = _clean(intervals)
    if not cleaned:
        return []
    cleaned.sort()
    merged = [cleaned[0]]
    for start, end in cleaned[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))
    return merged


def free_gaps(intervals, window):
    """Maximal sub-ranges of [ws, we) not covered by any interval."""
    ws, we = int(window[0]), int(window[1])
    if ws >= we:
        return []
    clipped = [(s, e) for s, e in _clean(intervals) if s < we and e > ws]
    clipped.sort()
    gaps = []
    cursor = ws
    for start, end in clipped:
        if start > cursor:
            gaps.append((cursor, start))
        if end > cursor:
            cursor = end
        if cursor >= we:
            break
    if cursor < we:
        gaps.append((cursor, we))
    return gaps


def max_overlap(intervals):
    """Largest number of non-empty intervals covering one common point."""
    cleaned = _clean(intervals)
    if not cleaned:
        return 0
    points = []
    for start, end in cleaned:
        points.append((start, 1))
        points.append((end, -1))
    # Process ends before starts at equal coordinates (half-open semantics).
    points.sort(key=lambda p: (p[0], p[1]))
    depth = best = 0
    for _, delta in points:
        depth += delta
        if depth > best:
            best = depth
    return best

"""LRU cache with per-entry time-to-live."""

from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self._capacity = int(capacity)
        self._clock = clock
        # key -> [value, deadline]; deadline is None for entries that never expire.
        self._entries = OrderedDict()

    def _is_expired(self, deadline, now=None):
        if deadline is None:
            return False
        if now is None:
            now = self._clock()
        return now >= deadline

    def _purge_expired(self, now=None):
        if now is None:
            now = self._clock()
        removed = [k for k, (_, deadline) in self._entries.items()
                   if self._is_expired(deadline, now)]
        for key in removed:
            del self._entries[key]
        return len(removed)

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        now = self._clock()
        deadline = None if ttl is None else now + ttl
        if key in self._entries:
            self._entries[key] = [value, deadline]
            self._entries.move_to_end(key)
            return
        if len(self._entries) >= self._capacity:
            self._purge_expired(now)
            if len(self._entries) >= self._capacity:
                self._entries.popitem(last=False)
        self._entries[key] = [value, deadline]

    def get(self, key, default=None):
        if key in self._entries:
            value, deadline = self._entries[key]
            if self._is_expired(deadline):
                del self._entries[key]
                return default
            self._entries.move_to_end(key)
            return value
        return default

    def __contains__(self, key):
        if key not in self._entries:
            return False
        _, deadline = self._entries[key]
        return not self._is_expired(deadline)

    def __len__(self):
        self._purge_expired()
        return len(self._entries)

    def keys(self):
        self._purge_expired()
        return list(self._entries.keys())

    def evict_expired(self):
        return self._purge_expired()

"""Recursive-descent arithmetic expression evaluator (no eval/ast)."""

# Token kinds
NUM, NAME, OP, LPAREN, RPAREN, COMMA = "NUM", "NAME", "OP", "LPAREN", "RPAREN", "COMMA"

_FUNCTIONS = ("min", "max", "abs")


def _tokenize(text):
    tokens = []
    i, n = 0, len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
        elif ch in "0123456789." or (ch == "." and i + 1 < n and text[i + 1].isdigit()):
            start = i
            seen_dot = False
            while i < n and (text[i].isdigit() or (text[i] == "." and not seen_dot)):
                if text[i] == ".":
                    seen_dot = True
                i += 1
            # Reject digits immediately after the dot with no digit, e.g. "1." handled below.
            raw = text[start:i]
            if raw == ".":
                raise ValueError("malformed number: '.'")
            if seen_dot and not (raw.count(".") and any(c.isdigit() for c in raw)):
                raise ValueError("malformed number: %r" % raw)
            if not any(c.isdigit() for c in raw):
                raise ValueError("malformed number: %r" % raw)
            if seen_dot:
                tokens.append((NUM, float(raw)))
            else:
                tokens.append((NUM, int(raw)))
        elif ch.isalpha() or ch == "_":
            start = i
            while i < n and (text[i].isalnum() or text[i] == "_"):
                i += 1
            tokens.append((NAME, text[start:i]))
        elif ch == "(":
            tokens.append((LPAREN, ch))
            i += 1
        elif ch == ")":
            tokens.append((RPAREN, ch))
            i += 1
        elif ch == ",":
            tokens.append((COMMA, ch))
            i += 1
        elif text[i:i + 2] in ("**", "//"):
            tokens.append((OP, text[i:i + 2]))
            i += 2
        elif ch in "+-*/%":
            tokens.append((OP, ch))
            i += 1
        else:
            raise ValueError("unknown character: %r" % ch)
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return (None, None)

    def advance(self):
        token = self.peek()
        self.pos += 1
        return token

    def parse(self):
        if not self.tokens:
            raise ValueError("empty expression")
        value = self.expr()
        if self.pos != len(self.tokens):
            raise ValueError("unexpected token after expression: %r" % (self.peek()[1],))
        return value

    def expr(self):
        return self.additive()

    def additive(self):
        left = self.multiplicative()
        while self.peek() == (OP, "+") or self.peek() == (OP, "-"):
            op = self.advance()[1]
            right = self.multiplicative()
            left = left + right if op == "+" else left - right
        return left

    def multiplicative(self):
        left = self.unary()
        while self.peek()[0] == OP and self.peek()[1] in ("*", "/", "//", "%"):
            op = self.advance()[1]
            right = self.unary()
            if op == "*":
                left = left * right
            elif op == "/":
                left = left / right  # ZeroDivisionError propagates
            elif op == "//":
                left = left // right
            else:
                left = left % right
        return left

    def power(self):
        base = self.unary()
        if self.peek() == (OP, "**"):
            self.advance()
            # Right-associative: exponent is another power expression.
            exponent = self.power()
            return base ** exponent
        return base

    def unary(self):
        kind, value = self.peek()
        if kind == OP and value in ("+", "-"):
            self.advance()
            operand = self.unary()
            return -operand if value == "-" else operand
        return self.power()

    def primary(self):
        kind, value = self.advance()
        if kind == NUM:
            return value
        if kind == LPAREN:
            inner = self.expr()
            if self.peek()[0] != RPAREN:
                raise ValueError("unbalanced parentheses")
            self.advance()
            return inner
        if kind == NAME:
            if value not in _FUNCTIONS:
                raise ValueError("unknown name: %r" % value)
            if self.peek()[0] != LPAREN:
                raise ValueError("expected '(' after function name %r" % value)
            self.advance()
            args = [self.expr()]
            while self.peek()[0] == COMMA:
                self.advance()
                args.append(self.expr())
            if self.peek()[0] != RPAREN:
                raise ValueError("unbalanced parentheses in call %r" % value)
            self.advance()
            if value == "abs":
                if len(args) != 1:
                    raise ValueError("abs takes exactly 1 argument")
                return abs(args[0])
            if len(args) < 1:
                raise ValueError("%s takes at least 1 argument" % value)
            if value == "min":
                return min(args)
            return max(args)
        raise ValueError("unexpected token: %r" % (value,))


def evaluate(text):
    if not isinstance(text, str):
        raise ValueError("input must be a string")
    return _Parser(_tokenize(text)).parse()

